correctedCode:
#include <stdio.h>
#include <string.h>

int main() {
    char greeting[20] = "Hi ";
    char name[] = "Alexandria";
    strncat(greeting, name, sizeof(greeting) - strlen(greeting) - 1);
    printf("%s\n", greeting);
    return 0;
}
